  function currentEngagement(){ return engagements.find(record=>record.engagement_id===data.consultingEngagementId) || null; }
  function discoveryFieldMarkup(discovery){ return DISCOVERY_SECTIONS.map((section,index)=>`<details class="discovery-section" ${index===0?'open':''}><summary><strong>${esc(section.title)}</strong><span>${section.fields.length} structured inputs</span></summary><p class="quiet-note">Each entered statement needs a classification and a source or reviewer reference. Unknown remains explicit.</p><div class="form-grid">${section.fields.map(([field,label])=>{const statement=discovery[section.id][field];return `<div class="discovery-statement full"><label>${esc(label)}<textarea rows="2" maxlength="4000" data-discovery-section="${esc(section.id)}" data-discovery-field="${esc(field)}" data-discovery-property="value" placeholder="Enter only what is currently known, asserted, inferred, assumed, estimated, or unknown.">${esc(statement.value)}</textarea></label><div class="form-grid discovery-metadata"><label>Classification<select data-discovery-section="${esc(section.id)}" data-discovery-field="${esc(field)}" data-discovery-property="state">${DISCOVERY_STATES.map(state=>`<option ${statement.state===state?'selected':''}>${esc(state)}</option>`).join('')}</select></label><label>Source or reviewer reference<input maxlength="512" value="${esc(statement.source)}" data-discovery-section="${esc(section.id)}" data-discovery-field="${esc(field)}" data-discovery-property="source" placeholder="Interview, document, observation, or reviewer"></label></div></div>`;}).join('')}</div></details>`).join(''); }
  function collectDiscovery(form){ const discovery=normalizeDiscovery(); $$('[data-discovery-property]',form).forEach(element=>{const section=element.dataset.discoverySection, field=element.dataset.discoveryField, property=element.dataset.discoveryProperty;discovery[section][field][property]=element.value;}); return discovery; }
  function renderDiscovery(){ const status=$('#discovery-status'), detail=$('#discovery-local-status'), form=$('#discovery-form'), fields=$('#discovery-fields'); if(!status||!detail||!form||!fields)return; if(!consultingMode){status.textContent='Local mode required';form.hidden=true;detail.innerHTML='<p class="quiet-note">Start the local launcher and open <code>http://127.0.0.1:8766/index.html?mode=consulting</code>. Hosted deployments do not store consulting discovery records.</p>';return;} const engagement=currentEngagement(); if(!engagement){status.textContent='Select engagement';form.hidden=true;detail.innerHTML='<p class="quiet-note">Open a local engagement from Engagement workspace before recording discovery. No discovery statement will be stored without its engagement reference.</p>';return;} const summary=discoveryCompleteness(engagement.discovery);status.textContent=`${summary.recorded} of ${summary.total} captured`;status.classList.toggle('complete',summary.complete);detail.innerHTML=`<p><strong>${esc(engagement.engagement_title)}</strong> / ${esc(engagement.client_name)}. ${summary.recorded} statements entered; ${summary.unknown} remain classified Unknown; ${summary.sourced} have a source or reviewer reference. Completeness is not correctness or validation.</p>`;form.hidden=false;form.elements.engagement_id.value=engagement.engagement_id;fields.innerHTML=discoveryFieldMarkup(normalizeDiscovery(engagement.discovery)); }
  function renderEngagementEvidence(){ const status=$('#engagement-evidence-status'), detail=$('#engagement-evidence-local-status'), form=$('#engagement-evidence-form'), table=$('#engagement-evidence-table'), summaryTarget=$('#engagement-evidence-summary'), rows=$('#engagement-evidence-rows'); if(!status||!detail||!form||!table||!summaryTarget||!rows)return; if(!consultingMode){status.textContent='Local mode required';form.hidden=true;table.hidden=true;detail.innerHTML='<p class="quiet-note">Start the loopback launcher and open consulting mode. Hosted deployments do not store engagement evidence metadata.</p>';return;} const engagement=currentEngagement(); if(!engagement){status.textContent='Select engagement';form.hidden=true;table.hidden=true;detail.innerHTML='<p class="quiet-note">Open a local engagement before adding its evidence or document metadata.</p>';return;} const records=(engagement.evidence_register||[]).map(normalizeEngagementEvidence), summary=evidenceSummary(records);status.textContent=`${summary.total} records`;status.classList.toggle('complete',summary.reviewRequired===0&&summary.unknown===0&&summary.total>0);detail.innerHTML=`<p><strong>${esc(engagement.engagement_title)}</strong> / ${esc(engagement.client_name)}. ${summary.reviewRequired} records require qualified review; ${summary.unknown} remain classified Unknown. Document supply is not validation.</p>`;form.hidden=false;table.hidden=false;summaryTarget.textContent=`${summary.total} local metadata records; ${summary.superseded} superseded. No source file is uploaded, interpreted, or treated as legally sufficient.`;rows.innerHTML=records.length?records.map(record=>`<tr><td><strong>${esc(record.title)}</strong><br><small>${esc(record.evidence_id)}</small><br><small>${esc(record.evidence_type)}</small></td><td>${esc(record.classification)}<br><small>${esc(record.review_state)}</small></td><td>${esc(record.source_reference)}<br><small>${esc(record.reviewer||'No reviewer recorded')}</small></td><td>${esc(record.relevance)}<br><small>${esc(record.limitation_or_gap||'No limitation recorded')}</small></td><td>${esc(record.linked_discovery_references||'None')}</td></tr>`).join(''):'<tr><td colspan="5" class="quiet-note">No evidence or document metadata recorded. Add only a controlled reference and its explicit review state.</td></tr>'; }
  async function addEngagementEvidence(event){ event.preventDefault(); const engagement=currentEngagement(), form=event.currentTarget;if(!engagement)return;const evidence=normalizeEngagementEvidence(getForm(form)), errors=engagementEvidenceErrors(evidence);if(errors.length){toast(errors.join(' '));return;}try{const saved=await localEngagementRequest(`/api/engagements/${encodeURIComponent(engagement.engagement_id)}/evidence`,{method:'POST',body:JSON.stringify(evidence)});engagements=engagements.map(record=>record.engagement_id===engagement.engagement_id?{...record,evidence_register:[...(record.evidence_register||[]),saved]}:record);form.reset();renderEngagementEvidence();renderEngagements();toast('Local evidence metadata appended; qualified review remains separate.');}catch(error){toast(error.message);}}
  function renderAiNecessity(){ const status=$('#ai-necessity-status'), detail=$('#ai-necessity-local-status'), form=$('#ai-necessity-form'), result=$('#ai-necessity-result');if(!status||!detail||!form||!result)return;if(!consultingMode){status.textContent='Local mode required';form.hidden=true;result.hidden=true;return;}const engagement=currentEngagement();if(!engagement){status.textContent='Select engagement';form.hidden=true;result.hidden=true;detail.innerHTML='<p class="quiet-note">Open a local engagement before recording an AI Necessity Gate.</p>';return;}const gate=aiNecessityAssessment(engagement.ai_necessity);status.textContent=gate.outcome.startsWith('CONDITIONALLY')?'Conditional review':'Hold';status.classList.toggle('complete',gate.outcome.startsWith('CONDITIONALLY'));detail.innerHTML=`<p><strong>${esc(engagement.engagement_title)}</strong> / ${esc(engagement.client_name)}. This gate tests only whether a bounded comparison may be reviewed; it does not recommend or authorize AI.</p>`;setForm(form,normalizeAiNecessity(engagement.ai_necessity));form.hidden=false;result.hidden=false;result.innerHTML=`<strong>${esc(gate.outcome)}</strong><p>${esc(gate.rationale)}</p>${gate.missing.length?`<p class="quiet-note">Unresolved: ${esc(gate.missing.join('; '))}</p>`:''}`;}
