  function renderFindingsQuestions(){ const status=$('#findings-questions-status'), detail=$('#findings-questions-local-status'), findingForm=$('#finding-form'), questionForm=$('#open-question-form'), summaryTarget=$('#findings-questions-summary'), findingRows=$('#finding-rows'), questionRows=$('#open-question-rows');if(!status||!detail||!findingForm||!questionForm||!summaryTarget||!findingRows||!questionRows)return;if(!consultingMode){status.textContent='Local mode required';findingForm.hidden=true;questionForm.hidden=true;return;}const engagement=currentEngagement();if(!engagement){status.textContent='Select engagement';findingForm.hidden=true;questionForm.hidden=true;detail.innerHTML='<p class="quiet-note">Open a local engagement before recording findings or open questions.</p>';return;}const findings=(engagement.findings_register||[]).map(normalizeFinding), questions=(engagement.open_questions_register||[]).map(normalizeOpenQuestion), summary=findingsSummary(findings,questions);status.textContent=summary.decisionBlocking?`${summary.decisionBlocking} decision-blocking`:'No decision-blocking items';status.classList.toggle('complete',summary.decisionBlocking===0);detail.innerHTML=`<p><strong>${esc(engagement.engagement_title)}</strong> / ${esc(engagement.client_name)}. Findings and questions are controlled review inputs, not recommendations, authority, compliance determinations, or resolved facts.</p>`;findingForm.hidden=false;questionForm.hidden=false;summaryTarget.textContent=`${summary.findings} findings; ${summary.questions} questions; ${summary.highUnresolved} high or decision-critical unresolved findings; ${summary.unresolvedQuestions} unresolved questions.`;findingRows.innerHTML=findings.length?findings.map(item=>`<tr><td><strong>${esc(item.title)}</strong><br><small>${esc(item.finding_id)}</small></td><td>${esc(item.domain)} / ${esc(item.severity)}<br><small>${esc(item.status)} / ${esc(item.decision_impact)}</small></td><td>${esc(item.supporting_evidence)}<br><small>${esc(item.contradictory_evidence||'No contradictory evidence recorded')}</small></td><td>${esc(item.owner)}<br><small>${esc(item.required_action)}</small></td></tr>`).join(''):'<tr><td colspan="4" class="quiet-note">No findings recorded. A lack of records does not establish that no issue exists.</td></tr>';questionRows.innerHTML=questions.length?questions.map(item=>`<tr><td><strong>${esc(item.question)}</strong><br><small>${esc(item.question_id)}</small></td><td>${esc(item.domain)} / ${esc(item.decision_impact)}<br><small>${esc(item.status)}</small></td><td>${esc(item.evidence_needed)}</td><td>${esc(item.owner)}<br><small>${esc(item.resolution||'No resolution recorded')}</small></td></tr>`).join(''):'<tr><td colspan="4" class="quiet-note">No open questions recorded. An absent question is not an answered question.</td></tr>'; }
