  function renderRecommendation(){const status=$('#recommendation-status'),detail=$('#recommendation-local-status'),readinessTarget=$('#recommendation-readiness'),form=$('#recommendation-form'),historyTarget=$('#recommendation-history'),rows=$('#recommendation-history-rows');if(!status||!detail||!readinessTarget||!form||!historyTarget||!rows)return;if(!consultingMode){status.textContent='Local mode required';form.hidden=true;historyTarget.hidden=true;readinessTarget.hidden=true;return;}const engagement=currentEngagement();if(!engagement){status.textContent='Select engagement';form.hidden=true;historyTarget.hidden=true;readinessTarget.hidden=true;detail.innerHTML='<p class="quiet-note">Open a local engagement before recording a consultant recommendation.</p>';return;}const readiness=recommendationReadiness(engagement),current=normalizeRecommendation(engagement.recommendation||{}),history=engagement.recommendation_history||[];status.textContent=history.length?`Version ${history.length} recorded`:readiness.status.startsWith('READY')?'Ready for judgment':'Exceptions visible';status.classList.toggle('complete',readiness.status.startsWith('READY'));detail.innerHTML=`<p><strong>${esc(engagement.engagement_title)}</strong> / ${esc(engagement.client_name)}. ${esc(readiness.note)}</p>`;readinessTarget.hidden=false;readinessTarget.innerHTML=`<strong>${esc(readiness.status)}</strong><p>${readiness.conditions.length?`Explicit conditions: ${esc(readiness.conditions.join('; '))}`:'No configured readiness exceptions were found. Consultant judgment remains required.'}</p><p class="quiet-note">AI Necessity Gate: ${esc(readiness.aiOutcome)}. This indicator does not select a recommendation or grant implementation authority.</p>`;setForm(form,current);form.hidden=false;historyTarget.hidden=false;rows.innerHTML=history.length?history.map(item=>`<tr><td>v${esc(item.version)}<br><small>${esc(item.recommendation_id)}</small></td><td><strong>${esc(item.recommendation)}</strong><br><small>${esc(item.executive_summary)}</small></td><td>${esc(item.consultant)}<br><small>${esc(item.decision_date)}</small></td><td>${esc(item.review_trigger)}</td></tr>`).join(''):'<tr><td colspan="4" class="quiet-note">No consultant recommendation recorded. Readiness does not make one automatically.</td></tr>';}
