  function renderExecutivePackage(){const status=$('#executive-package-status'),detail=$('#executive-package-local-status'),preview=$('#executive-package-preview'),actions=$('#executive-package-actions');if(!status||!detail||!preview||!actions)return;if(!consultingMode){status.textContent='Local mode required';detail.innerHTML='<p class="quiet-note">Executive packages are available only for local consulting engagements.</p>';preview.hidden=true;actions.hidden=true;return;}const report=executivePackage();if(!report){status.textContent='Select engagement';detail.innerHTML='<p class="quiet-note">Open a local engagement before generating a decision package.</p>';preview.hidden=true;actions.hidden=true;return;}status.textContent=report.recommendation==='NOT YET RECORDED'?'Recommendation not recorded':'Generated from current local record';status.classList.toggle('complete',report.recommendation!=='NOT YET RECORDED');detail.innerHTML=`<p><strong>${esc(report.title)}</strong>. This package is generated from the current local engagement state. It is not stored as an R8 snapshot and does not create authority, approval, compliance, or implementation.</p>`;preview.hidden=false;actions.hidden=false;preview.innerHTML=executiveDecisionPackageBody(report);}
