  async function renderSnapshots(){const status=$('#snapshots-status'),detail=$('#snapshots-local-status'),table=$('#snapshot-history'),rows=$('#snapshot-history-rows');if(!status||!detail||!table||!rows)return;if(!consultingMode){status.textContent='Local mode required';table.hidden=true;return;}const engagement=currentEngagement();if(!engagement){status.textContent='Select engagement';detail.innerHTML='<p class="quiet-note">Open a local engagement before reviewing issued snapshots.</p>';table.hidden=true;return;}status.textContent='Loading';table.hidden=true;try{const result=await localEngagementRequest(`/api/engagements/${encodeURIComponent(engagement.engagement_id)}/snapshots`);if(currentEngagement()?.engagement_id!==engagement.engagement_id)return;engagementSnapshots=result.snapshots||[];status.textContent=engagementSnapshots.length?`${engagementSnapshots.length} issued`:'None issued';status.classList.toggle('complete',engagementSnapshots.length>0);detail.innerHTML='<p>Snapshots are immutable local records created with a consultant recommendation. Reassessment creates a new snapshot; none can be overwritten here.</p>';table.hidden=false;rows.innerHTML=engagementSnapshots.length?engagementSnapshots.map(snapshot=>`<tr><td><strong>${esc(snapshot.snapshot_id)}</strong></td><td>${esc(snapshot.created_at)}</td><td>${esc(snapshot.recommendation_id)}</td><td><code>${esc(snapshot.content_sha256)}</code></td><td><button type="button" class="download-snapshot" data-snapshot-id="${esc(snapshot.snapshot_id)}">Download JSON</button></td></tr>`).join(''):'<tr><td colspan="5" class="quiet-note">No snapshot has been issued. Recording a consultant recommendation creates the first immutable snapshot.</td></tr>';$$('.download-snapshot').forEach(button=>button.addEventListener('click',()=>downloadSnapshot(engagement.engagement_id,button.dataset.snapshotId)));}catch(error){status.textContent='Unavailable';detail.innerHTML=`<p class="quiet-note">${esc(error.message)}</p>`;}}
