  function applyDiscoveryToOpportunity(){ const engagement=currentEngagement();if(!engagement)return;const discovery=normalizeDiscovery(engagement.discovery);const get=(section,field)=>discovery[section][field].value.trim();const applied={name:engagement.initiative_name,sponsor:get('governance','accountable_executive')||engagement.executive_sponsor,deadline:engagement.target_decision_date,capability:get('current_operating_model','current_workflow'),problem:get('business_problem','problem_statement'),decision:engagement.decision_question,evidenceOwner:get('governance','process_owner')||engagement.business_owner,evidenceState:'Requested'};let count=0;for(const [key,value] of Object.entries(applied)){if(value&&!String(data.opportunity[key]||'').trim()){data.opportunity[key]=value;count+=1;}}data.consultingDiscoveryLink={engagement_id:engagement.engagement_id,applied_at:new Date().toISOString(),statement_classifications:Object.fromEntries([['business_problem','problem_statement'],['current_operating_model','current_workflow'],['governance','accountable_executive']].map(([section,field])=>[`${section}.${field}`,discovery[section][field].state]))};persist();toast(`${count} discovery fields copied as draft ROI-EA input; no statement was validated or authorized.`);}
