  function exportDossier(){ const o=data.opportunity,b=calculatedBaseline(),r=data.risk,a=data.architecture,p=data.pilot,choice=preferredAlternative(); const riskBand=Object.keys(r).length?(riskScore()>=10?'High':riskScore()>=5?'Moderate':'Lower'):'Not assessed'; const html=`<!doctype html><html><head><meta charset="utf-8"><title>Executive Decision Dossier</title><style>body{font:11pt/1.45 Georgia,serif;color:#11253b;max-width:7.2in;margin:.65in auto}h1{font:28pt/1.05 Arial,sans-serif;margin:0 0 4px}h2{font:15pt Arial,sans-serif;border-bottom:1px solid #a8bcc9;padding-bottom:5px;margin-top:25px}.eyebrow{font:700 9pt Arial,sans-serif;letter-spacing:1.2px;color:#0b7778}.meta{color:#52687a}table{border-collapse:collapse;width:100%;margin:10px 0}th,td{border:1px solid #c8d3da;padding:7px;text-align:left;vertical-align:top}th{background:#edf3f6;width:34%}.notice{background:#f5f1e8;border-left:4px solid #c8943d;padding:10px}footer{margin-top:35px;color:#617484;font:9pt Arial,sans-serif}@media print{body{margin:.45in auto}}</style></head><body><span class="eyebrow">AI AT HUMAN SCALE / ROI-DRIVEN ENTERPRISE ARCHITECT</span><h1>Executive Decision Dossier</h1><p class="meta">Generated ${new Date().toLocaleDateString()} | Draft for qualified review</p><h2>1. Decision request</h2><table><tr><th>Opportunity</th><td>${esc(o.name||'Not stated')}</td></tr><tr><th>Costly work</th><td>${esc(o.problem||'Not stated')}</td></tr><tr><th>Requested decision</th><td>${esc(o.decision||'Not stated')}</td></tr><tr><th>Sponsor / deadline</th><td>${esc(o.sponsor||'Not named')} / ${esc(o.deadline||'Not set')}</td></tr><tr><th>Evidence owner / state</th><td>${esc(o.evidenceOwner||'Not named')} / ${esc(o.evidenceState||'Not stated')}</td></tr></table><h2>2. Economic position</h2><table><tr><th>Current annual cost</th><td>${money(b.current)}</td></tr><tr><th>Forecast net annual benefit</th><td>${money(b.benefit)}</td></tr><tr><th>Implementation / recurring cost</th><td>${money(b.implementation)} / ${money(data.baseline.recurringCost)}</td></tr><tr><th>Payback / first-year ROI</th><td>${b.payback===null?'Not available':number(b.payback*12)+' months'} / ${b.roi===null?'Not available':number(b.roi)+'%'}</td></tr><tr><th>Value / evidence classification</th><td>${esc(data.baseline.valueClass||'Not stated')} / ${esc(data.baseline.baselineEvidence||'Not stated')}</td></tr></table><h2>3. Agentic-risk boundary</h2><table><tr><th>Screening result</th><td>${riskBand} (${Object.keys(r).length?riskScore():'Not assessed'} points)</td></tr><tr><th>System role / action capability</th><td>${esc(r.systemRole||'Not stated')} / ${esc(r.actionCapability||'Not stated')}</td></tr><tr><th>Human authority / approval</th><td>${esc(r.decisionAuthority||'Not named')} / ${esc(r.humanApproval||'Not stated')}</td></tr><tr><th>Fallback</th><td>${esc(r.fallback||'Not stated')}</td></tr><tr><th>Risk conditions</th><td>${esc(r.mitigations||'Not stated')}</td></tr></table><h2>4. Architecture decision</h2><table><tr><th>Decision</th><td>${esc(a.title||'Not stated')}</td></tr><tr><th>Status / authority</th><td>${esc(a.decisionStatus||'Not stated')} / ${esc(a.authority||'Not named')}</td></tr><tr><th>Preferred alternative</th><td>${esc(choice?.name||'Not selected')}</td></tr><tr><th>Conditions</th><td>${esc(a.conditions||'Not stated')}</td></tr><tr><th>Rationale</th><td>${esc(a.rationale||'Not stated')}</td></tr></table><h2>5. Pilot charter</h2><table><tr><th>Pilot / owner</th><td>${esc(p.pilotName||'Not stated')} / ${esc(p.pilotOwner||'Not named')}</td></tr><tr><th>Hypothesis</th><td>${esc(p.hypothesis||'Not stated')}</td></tr><tr><th>Metric / target</th><td>${esc(p.metric||'Not stated')} / ${esc(p.metricTarget||'Not stated')}</td></tr><tr><th>Scope and exclusions</th><td>${esc(p.scope||'Not stated')}</td></tr><tr><th>Guardrails</th><td>${esc(p.guardrails||'Not stated')}</td></tr><tr><th>Stop / go-no-go rules</th><td>${esc(p.stopRules||'Not stated')}<br><br>${esc(p.goNoGo||'Not stated')}</td></tr></table><p class="notice"><b>Decision boundary:</b> This dossier supports a human decision. It does not establish legal compliance, certify security controls, or prove a forecast benefit. Material claims, controls, and results require qualified review and recorded evidence.</p><footer>© 2026 David C. Jones. All rights reserved. AI at Human Scale.<br>ROI-Driven Enterprise Architect MVP | Decision, value, authority, and evidence should remain traceable through the delivery lifecycle.</footer></body></html>`; const win=window.open('','_blank'); if(!win){toast('Popup blocked. Allow popups to export the dossier.');return;} win.document.write(html); win.document.close(); win.focus(); setTimeout(()=>win.print(),250); }
  function exportDossier(){
    const evidence=(data.evidence||[]).map(r=>`<tr><td>${esc(r.claim)}</td><td>${esc(r.area)}</td><td>${esc(r.recordType)}</td><td>${esc(r.state)}</td><td>${esc(r.source)}<br><small>${esc(r.sourceOwner)}</small></td><td>${esc(r.limitation||'None stated')}</td></tr>`).join('') || '<tr><td colspan="6">No evidence records added.</td></tr>';
    const html=`<!doctype html><html><head><meta charset="utf-8"><title>Executive Decision Dossier</title><style>body{font:11pt/1.45 Georgia,serif;color:#11253b;max-width:7.2in;margin:.65in auto}h1{font:28pt/1.05 Arial,sans-serif;margin:0 0 4px}h2{font:15pt Arial,sans-serif;border-bottom:1px solid #a8bcc9;padding-bottom:5px;margin-top:25px}h3{font:14pt Arial,sans-serif;margin:18px 0 5px}h4{font:12pt Arial,sans-serif;margin:10px 0 4px;color:#154b7a}.eyebrow{font:700 9pt Arial,sans-serif;letter-spacing:1.2px;color:#0b7778}.meta,.quiet-note{color:#52687a}table{border-collapse:collapse;width:100%;margin:10px 0;font-size:9.5pt}th,td{border:1px solid #c8d3da;padding:7px;text-align:left;vertical-align:top}th{background:#edf3f6}.notice{background:#f5f1e8;border-left:4px solid #c8943d;padding:10px}footer{margin-top:35px;color:#617484;font:9pt Arial,sans-serif}@media print{body{margin:.45in auto}}</style></head><body><span class="eyebrow">AI AT HUMAN SCALE / ROI-DRIVEN ENTERPRISE ARCHITECT</span><h1>Executive Decision Dossier</h1><p class="meta">Generated ${new Date().toLocaleDateString()} | Draft for qualified review</p>${$('#dossier-summary').innerHTML}<h2>Traceability index</h2><table><thead><tr><th>Claim / data point</th><th>Area</th><th>Type</th><th>State</th><th>Source / owner</th><th>Limitation or next action</th></tr></thead><tbody>${evidence}</tbody></table><p class="notice"><b>Decision boundary:</b> This dossier supports a human decision. It does not establish legal compliance, certify security controls, or prove a forecast benefit. Material claims, controls, and results require qualified review and recorded evidence.</p><footer>© 2026 David C. Jones. All rights reserved. AI at Human Scale.<br>ROI-Driven Enterprise Architect MVP | Decision, value, authority, and evidence should remain traceable through the delivery lifecycle.</footer></body></html>`;
    const win=window.open('','_blank'); if(!win){toast('Popup blocked. Allow popups to export the dossier.');return;} win.document.write(html); win.document.close(); win.focus(); setTimeout(()=>win.print(),250);
  }
  function downloadJson(){ const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}); const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='roi-ea-working-record.json'; a.click(); URL.revokeObjectURL(a.href); }
  function wireFederated(){ const buttons=$$('.federated-tab'), panels=$$('[data-federated-panel]'); buttons.forEach(button=>button.addEventListener('click',()=>{ const view=button.dataset.federatedView; buttons.forEach(item=>item.classList.toggle('active',item===button)); panels.forEach(panel=>{ const active=panel.dataset.federatedPanel===view; panel.classList.toggle('active',active); panel.hidden=!active; }); })); }
  function wireGlobal(){ $$('.nav-link').forEach(el=>el.addEventListener('click',()=>show(el.dataset.view))); $('#load-demo').addEventListener('click',()=>{data=sample(); const draft={id:'AE-SCHED-001',aiSystem:'Scheduling preparation assistant',aiSystemId:'AIS-SCHED-PREP',businessCapability:'Service scheduling',businessCapabilityId:'CAP-SERVICE-SCHEDULING',authorityOwner:'Maya Chen, VP Operations',status:'Active - controlled pilot',effectiveDate:'2026-10-20',reviewDate:'2026-12-18',inventoryRefs:'Scheduling Hub; Field Service Platform API',actionIds:'ACT-READ-RECORDS; ACT-PREPARE-CONTEXT; ACT-DRAFT-SUMMARY',resourceIds:'RES-APPROVED-RECORDS; RES-SCHEDULING-REGION',permittedActions:'Read approved internal records; prepare case context; draft internal coordinator summary.',prohibitedActions:'No scheduling write-back, external communication, customer commitment, or autonomous decision.',resourceScope:'One service region; eligible weekday exceptions; approved internal records only; no production write credential.',evidenceRefs:'MVP evidence: coordinator time-study statement; security design review. ERIR: APP-FTC-001; CTL-CLAIMS-001; EVD-CLAIMS-001.',evidenceRequirement:'A qualified reviewer must assess the privacy/security design evidence and pilot measurement before authority becomes effective.',acceptanceCriterion:'Explicit reviewer assessment records accepted, current evidence and no material unresolved guardrail failure.',evidenceArtifactIds:'MVP-EVD-001; MVP-EVD-002; EVD-CLAIMS-001',evidenceAssessmentState:'not assessed',evidenceValidFrom:'2026-10-20',evidenceValidUntil:'2026-12-18',evidenceReviewer:'Not yet assessed',evidenceReviewAuthority:'Maya Chen, VP Operations',monitoringTriggers:'Measurement owner records preparation time and guardrail exceptions weekly; investigate a material accuracy or privacy concern immediately.',revocationConditions:'Maya Chen may constrain, suspend, or revoke on a material privacy concern, repeated material inaccuracy, unauthorized access attempt, or loss of manual fallback.',decision:'Authorize',decisionDate:'2026-10-20',rationale:'Illustrative controlled-pilot authority only. Required evidence remains subject to qualified review; no control effectiveness or realized benefit is asserted.'}; data.authorityEnvelope=appendDecision(normalizeAuthority(draft,authorityContext()),{decision:'Authorize',decisionAuthority:draft.authorityOwner,decisionDate:draft.effectiveDate,rationale:draft.rationale,resultingState:draft.status,evidenceReferences:draft.evidenceArtifactIds}); data.authorityEnvelopes=[data.authorityEnvelope];persist(); wireForms();toast('Northstar example loaded.');}); $('#reset-data').addEventListener('click',()=>{if(confirm('Reset all locally stored MVP data?')){data=structuredClone(blank);persist();wireForms();toast('Local data reset.');}}); $('#export-html').addEventListener('click',exportDossier); $('#download-json').addEventListener('click',downloadJson); }
